fn read_u32(b: &[u8], off: &mut usize) -> u32 {
    let v = u32::from_le_bytes([b[*off], b[*off + 1], b[*off + 2], b[*off + 3]]);
    *off += 4;
    v
}

fn read_i64(b: &[u8], off: &mut usize) -> i64 {
    let mut buf = [0u8; 8];
    buf.copy_from_slice(&b[*off..*off + 8]);
    *off += 8;
    i64::from_le_bytes(buf)
}

fn read_f64(b: &[u8], off: &mut usize) -> f64 {
    f64::from_bits(read_i64(b, off) as u64)
}

fn read_packed_portfolio_snapshot_positions<'a>(fbb: &mut flatbuffers::FlatBufferBuilder<'a>, ptr: *const u8, len: usize) -> Option<flatbuffers::WIPOffset<flatbuffers::Vector<'a, flatbuffers::ForwardsUOffset<backend::PortfolioPosition<'a>>>>> {
    if ptr.is_null() || len == 0 { return None; }
    let b = unsafe { std::slice::from_raw_parts(ptr, len) };
    let mut off = 0usize;
    let count = read_u32(b, &mut off) as usize;
    let mut offsets: Vec<flatbuffers::WIPOffset<backend::PortfolioPosition<'a>>> = Vec::with_capacity(count);
    for _ in 0..count {
        let symbol_len = read_u32(b, &mut off) as usize; let symbol = std::str::from_utf8(&b[off..off + symbol_len]).unwrap_or(""); off += symbol_len; let symbol_off = fbb.create_string(symbol);
        let quantity = read_i64(b, &mut off);
        let avg_price = read_f64(b, &mut off);
        let pnl = read_f64(b, &mut off);
        let item = backend::PortfolioPosition::create(fbb, &backend::PortfolioPositionArgs {
            symbol: Some(symbol_off),
            quantity,
            avg_price,
            pnl,
            ..Default::default()
        });
        offsets.push(item);
    }
    Some(fbb.create_vector(&offsets))
}

