pub fn serialize_event(event_id: u32, json: &[u8], out: &mut [u8]) -> Result<usize, TranscodeError> {
    match event_id {
        2995289047 => serialize_quote(json, out),
        1362521689 => serialize_trade(json, out),
        464274147 => serialize_portfolio(json, out),
        2318166199 => serialize_complex(json, out),
        1932267671 => serialize_order(json, out),
        3211729064 => serialize_big_val(json, out),
        1335831723 => serialize_hello(json, out),
        669089267 => serialize_welcome(json, out),
        2946386435 => serialize_subscribe(json, out),
        4190043798 => serialize_unsubscribe(json, out),
        3026600144 => serialize_join_group(json, out),
        3755061443 => serialize_leave_group(json, out),
        1249175018 => serialize_snapshot_request(json, out),
        375255177 => serialize_ping(json, out),
        2061178551 => serialize_pong(json, out),
        _ => Err(TranscodeError::UnknownEvent),
    }
}
